      const _sz=Number(l.size);if(_sz>0&&_sz!==1){for(let q=0,c=frag.lastChild;q<4&&c;q++,c=c.previousSibling)c.style.setProperty('--cw','calc(var(--cwb) * '+_sz+')')}
      if(selected.type==='node'&&(l.source===selected.id||l.target===selected.id||(l.a1&&l.a1.id===selected.id)||(l.a2&&l.a2.id===selected.id))){for(let q=0,c=frag.lastChild;q<4&&c;q++,c=c.previousSibling)c.classList.add('hl')}
