    if(selected.type==='node'){const n=nodeById(selected.id);if(!n)return;empty.style.display='none';ne.style.display='block';$('networkNodeLabel').value=n.label||'';$('networkNodeX').value=Math.round(n.x);$('networkNodeY').value=Math.round(n.y);$('networkNodeW').value=Math.round(n.w);$('networkNodeH').value=Math.round(n.h);fillImageSelect(n)}
