  $('networkApplyNodeBtn').addEventListener('click',()=>{const n=nodeById(selected.id);if(!n)return;n.label=$('networkNodeLabel').value.trim()||'Unnamed Device';n.image=$('networkNodeImage').value;n.x=Math.max(0,Number($('networkNodeX').value)||0);n.y=Math.max(0,Number($('networkNodeY').value)||0);n.w=Math.max(62,Number($('networkNodeW').value)||80);n.h=Math.max(48,Number($('networkNodeH').value)||60);render();updateStatus('Node updated — unsaved')});
