  render();
  /* ===== Attach free-drawn lines to devices (line ends follow the device when it is moved) ===== */
  function nodeBoxOf(n){return {x0:Number(n.x)||0,y0:Number(n.y)||0,x1:(Number(n.x)||0)+Math.max(62,Number(n.w)||80),y1:(Number(n.y)||0)+Math.max(48,Number(n.h)||60)}}
  function nearestNode(px,py,maxD){
    let best=null,bd=1e9;
    state.nodes.forEach(n=>{const b=nodeBoxOf(n),dx=Math.max(b.x0-px,0,px-b.x1),dy=Math.max(b.y0-py,0,py-b.y1),d=Math.hypot(dx,dy);if(d<bd){bd=d;best=n}});
    return best&&bd<=maxD?best:null;
  }
  function attachEnds(l,maxD){
    if(!l||!l.free)return 0;let c=0;
    [['a1','x1','y1'],['a2','x2','y2']].forEach(t=>{
      if(l[t[0]]&&nodeById(l[t[0]].id)){c++;return}
      const px=Number(l[t[1]])||0,py=Number(l[t[2]])||0,n=nearestNode(px,py,maxD);
      if(n){l[t[0]]={id:n.id,dx:Math.round(px-Number(n.x)),dy:Math.round(py-Number(n.y))};c++}
    });
    return c;
  }
  function attachInfoText(l){
    const nm=a=>{const n=a&&nodeById(a.id);return n?n.label:null};
    const A=nm(l.a1),B=nm(l.a2);
    return 'Start: '+(A?'attached to '+A:'free')+'  •  End: '+(B?'attached to '+B:'free');
  }
  function updateAttachBox(){
    const box=$('networkLinkAttachBox');if(!box)return;
    const l=selected.type==='link'?state.links.find(x=>x.id===selected.id):null;
    if(!l||!l.free){box.style.display='none';return}
    box.style.display='block';$('networkLinkAttachInfo').textContent=attachInfoText(l);
  }
  function linkKindInfo(l){
    if(isFiberLink(l))return {k:'fiber',name:'Fiber'};
    const c=String(l.color||'#111827').toLowerCase();
    if(/^#(111827|0b0d12|0a0c10|000|000000)$/.test(c))return {k:'cat6',name:'CAT6'};
    return {k:'c:'+c,name:'Same-colour'};
  }
  function selLink(){return selected.type==='link'?state.links.find(x=>x.id===selected.id):null}
